// Regenerates api/schema.gen.ts and api/models.gen.ts from the backend contract (../../openapi.yaml).
// Run: pnpm --filter @repo/core gen:api. Never edit the generated files by hand.
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const core = join(dirname(fileURLToPath(import.meta.url)), '..');
const contract = join(core, '..', '..', '..', 'openapi.yaml');
const schemaFile = join(core, 'api', 'schema.gen.ts');
execFileSync(process.execPath, [join(core, 'node_modules', 'openapi-typescript', 'bin', 'cli.js'), contract, '-o', schemaFile], { stdio: 'inherit' });

const source = readFileSync(schemaFile, 'utf8');
const block = source.slice(source.indexOf('    schemas: {'), source.indexOf('    responses: {'));
const names = [...block.matchAll(/^        (?:"([^"]+)"|([A-Za-z0-9_]+))\??: /gm)].map((m) => m[1] ?? m[2]);
const lines = [
  '// GENERATED by scripts/generate-api.mjs from openapi.yaml — do not edit.',
  "import type { components } from './schema.gen';",
  '',
  "type S = components['schemas'];",
  ...names.map((n) => `export type ${n} = S['${n}'];`),
  '',
];
writeFileSync(join(core, 'api', 'models.gen.ts'), lines.join('\n'));
console.log(`models.gen.ts: ${names.length} schema aliases`);
